import{_ as a,o,c as e,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const c=JSON.parse('{"title":"代理不是魔法：先画清一条连接","description":"","frontmatter":{"title":"代理不是魔法：先画清一条连接"},"headers":[],"relativePath":"proxy-software-course/01-proxy-mental-model.md","filePath":"proxy-software-course/docs/01-proxy-mental-model.md"}'),d={name:"proxy-software-course/01-proxy-mental-model.md"};function u(l,t,n,h,s,p){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="代理不是魔法-先画清一条连接" tabindex="-1">代理不是魔法：先画清一条连接 <a class="header-anchor" href="#代理不是魔法-先画清一条连接" aria-label="Permalink to &quot;代理不是魔法：先画清一条连接&quot;">​</a></h1><h2 id="一个说不清楚的现象" tabindex="-1">一个说不清楚的现象 <a class="header-anchor" href="#一个说不清楚的现象" aria-label="Permalink to &quot;一个说不清楚的现象&quot;">​</a></h2><p>假设你在用一个 Clash 类的规则代理工具。打开系统代理开关后，浏览器能打开一个原本连不上的网站，一切正常。你想验证代理是不是&quot;全局生效&quot;。于是在终端里跑一个用裸 socket 写的小脚本。它不读 <code>HTTP_PROXY</code> 环境变量，也不问系统要任何配置，直接对目标地址发起 TCP 连接。结果这个终端命令却超时了，连不上。你以为自己的代理配置有问题，于是又装了一个 TUN 模式（一种会在系统里出现一张虚拟网卡的运行方式）。开启之后，同一个脚本突然又能连通了。</p><p>配置文件没有变，规则也没有变。为什么同一个代理工具，对浏览器和这个小脚本的效果完全不同？这正是本章要拆开看的问题：一条网络连接从应用发出，到真正抵达目标服务器，中间经过了哪些&quot;决定&quot;，这些决定又是谁在做的。</p><h2 id="三段模型-入口、路由、出站" tabindex="-1">三段模型：入口、路由、出站 <a class="header-anchor" href="#三段模型-入口、路由、出站" aria-label="Permalink to &quot;三段模型：入口、路由、出站&quot;">​</a></h2><p>先把结论摆出来。任何一个正向代理（forward proxy，代表客户端去连接目标服务器的中间程序，目标服务器直接看到的连接方是代理而不是原始客户端）能处理一条连接，都要依次完成三件事。</p><table tabindex="0"><thead><tr><th>阶段</th><th>回答的问题</th><th>本课程后续对应</th></tr></thead><tbody><tr><td>入口（entry）</td><td>代理程序怎么才能看见这条连接</td><td>HTTP CONNECT 入口、SOCKS5 入口</td></tr><tr><td>路由（route）</td><td>这条连接该走直连、拒绝还是转发</td><td>规则引擎、DNS 策略</td></tr><tr><td>出站（outbound）</td><td>决定走转发之后，具体怎么连到目标</td><td>直连拨号器、SOCKS5 上游客户端</td></tr></tbody></table><p>这三段是本课程贯穿全书的骨架。一条连接如果没有进入&quot;入口&quot;，后面的&quot;路由&quot;和&quot;出站&quot;根本无从谈起。开头那个现象的答案，就藏在&quot;入口&quot;这一段里。</p><h2 id="系统代理-一个应用可以选择无视的建议" tabindex="-1">系统代理：一个应用可以选择无视的建议 <a class="header-anchor" href="#系统代理-一个应用可以选择无视的建议" aria-label="Permalink to &quot;系统代理：一个应用可以选择无视的建议&quot;">​</a></h2><p>系统代理（system proxy）是操作系统提供的一项设置：它把一个代理地址写进某个约定好的位置（环境变量、系统偏好设置、注册表）。愿意配合的应用会在发起连接之前先读这个设置，把请求改发给代理，而不是直接连目标。</p><p>关键词是&quot;愿意配合&quot;。系统代理不是内核层面的强制转发。它更像贴在门上的一张便签，写着&quot;出门请走侧门&quot;，但只有认字、并且愿意照做的人才会绕路。浏览器和大部分命令行工具都会主动读取这张便签，比如 <code>curl</code> 不带 <code>-x</code> 参数时也会读 <code>http_proxy</code> 变量。但一个直接调用 <code>net.Dial</code> 或裸 socket API 写成的小程序不一样。如果作者没有专门加读取系统代理设置的代码，它根本不知道有这张便签存在，会照常尝试连接目标地址。如果目标本来就连不通（它在你实际网络环境里就是不可达的），这条连接自然会一直挂到超时。这就是开头那个脚本卡住的原因：不是代理没生效，是这条连接压根没有进入代理的入口。</p><h2 id="tun-把决定权从应用手里收回来" tabindex="-1">TUN：把决定权从应用手里收回来 <a class="header-anchor" href="#tun-把决定权从应用手里收回来" aria-label="Permalink to &quot;TUN：把决定权从应用手里收回来&quot;">​</a></h2><p>TUN 是一种虚拟网络接口（virtual network interface），由操作系统内核提供，向用户态程序交付原始的 IP 数据包，而不是像网卡驱动那样交付以太网帧。这一边界记录在 <a href="https://docs.kernel.org/networking/tuntap.html" target="_blank" rel="noreferrer">Linux kernel TUN/TAP 文档</a> 里：TUN 交付三层 IP 包，TAP 交付二层帧。当代理工具开启 TUN 模式，它会创建这样一张虚拟网卡，并且修改系统路由表。原本要发往外部网络的 IP 包，改为经过这张虚拟网卡，交给代理程序处理。</p><p>这一步不再依赖应用&quot;愿不愿意&quot;读系统代理设置。只要这条连接产生的 IP 包会按路由表规则流向这张虚拟网卡，代理程序就能收到它，不管发出这个包的程序有没有写过任何代理相关代码。这解释了开头现象的后半段：开启 TUN 之后，那个原本不认系统代理这张便签的裸 socket 脚本，它发出的 IP 包被路由表拦下，转交给了代理程序，连接因此通了。</p><p>需要马上澄清一个常见误解：<strong>打开系统代理并不会自动接管设备上的全部流量</strong>。它只对读取这项设置的应用生效。要做到&quot;不管应用是否配合都能接管&quot;，需要 TUN 这类工作在网络层、由内核路由表决定去向的机制。系统代理和 TUN 想达成同一个目标，也就是让流量进入代理入口，但生效范围和实现层次完全不同，不能把二者混为一谈。</p><h2 id="正向代理不是反向代理-代理也不是-vpn" tabindex="-1">正向代理不是反向代理，代理也不是 VPN <a class="header-anchor" href="#正向代理不是反向代理-代理也不是-vpn" aria-label="Permalink to &quot;正向代理不是反向代理，代理也不是 VPN&quot;">​</a></h2><p>顺着&quot;谁在替谁连接&quot;这条线，还有两组容易混淆的概念值得当场分开。</p><p>正向代理代表客户端去连接目标，目标服务器只看得到代理的那一端连接。反向代理（reverse proxy）方向相反：它代表服务端接收客户端的连接，客户端通常把反向代理误当成了目标网站本身。二者的共同点只是&quot;中间有一个转发程序&quot;，谁替谁工作是相反的。因此反向代理不会出现在本课程的 mini-proxy 里，这里只做正向代理。</p><p>代理与 VPN（虚拟专用网）也不是同一个东西换了个名字。正向代理的入口通常只处理特定协议的连接，比如 HTTP 代理协议、SOCKS5 协议。VPN 通常在网络层建立一条加密隧道，把接口上出现的所有 IP 流量都送进隧道，不区分是哪个应用发出的、用的是什么应用层协议。TUN 模式的代理工具借用了和 VPN 类似的&quot;网络层接管&quot;手段。但它接住 IP 包之后，仍然按代理自己的规则做路由和出站决策，不是像多数 VPN 那样只把整个数据包原样转发到远端网关。</p><h2 id="数据面与规则引擎-到底谁说了算" tabindex="-1">数据面与规则引擎，到底谁说了算 <a class="header-anchor" href="#数据面与规则引擎-到底谁说了算" aria-label="Permalink to &quot;数据面与规则引擎，到底谁说了算&quot;">​</a></h2><p>再看开头那个容易忽略的第三个误解：<strong>代理节点决定规则，规则引擎只是界面上的一个功能开关</strong>。真实的分工反过来。判断一条连接该走直连、拒绝还是转发到某个节点，这个决策由路由这一段的规则引擎做出，依据是配置里的规则顺序（第 5 章会把它实现成一个可以运行的函数）。节点只是&quot;路由决策选择了转发&quot;之后，出站这一段要连接的下一跳，节点本身并不参与&quot;要不要用它&quot;这个判断。</p><p>这里可以顺带交代两个贯穿全书的角色划分。数据面（data plane）指逐条处理连接和字节的路径，也就是入口、路由、出站这三段实际跑起来的地方；控制面（control plane）指管理配置、规则、节点列表、运行状态和界面这一侧。规则文件和节点列表都是控制面的产物，但每条连接的实际判断和转发，都发生在数据面。本课程从这一章开始，专注在数据面：代理如何接住一条连接、如何判断它、如何把它送到目标。</p><h2 id="证据包-三个场景-三种入口命运" tabindex="-1">证据包：三个场景，三种入口命运 <a class="header-anchor" href="#证据包-三个场景-三种入口命运" aria-label="Permalink to &quot;证据包：三个场景，三种入口命运&quot;">​</a></h2><p>不写代码也能验证上面的结论：用三个场景对照实际会不会进入代理入口。请先根据前面的原理自己猜一遍，再核对下表。</p><table tabindex="0"><thead><tr><th>场景</th><th>是否读系统代理设置</th><th>是否受 TUN 路由表影响</th><th>是否进入代理入口</th></tr></thead><tbody><tr><td>浏览器发起的 HTTPS 请求</td><td>是，浏览器主动读取</td><td>是（IP 包同样会经过路由表）</td><td>是</td></tr><tr><td><code>curl -x http://127.0.0.1:8080 ...</code>（显式指定代理）</td><td>是，命令行参数直接指定</td><td>是</td><td>是</td></tr><tr><td>只用裸 socket 直连目标、且只开系统代理未开 TUN 的脚本</td><td>否</td><td>否（未开 TUN）</td><td>否，直接超时或直连失败</td></tr><tr><td>同一个裸 socket 脚本、但已开启 TUN</td><td>否</td><td>是</td><td>是，靠路由表而非应用配合</td></tr></tbody></table><p>这张表也回答了一个容易忽略的细节：即使只开 TUN 不改系统代理设置，应用自己发出的 DNS 查询同样会经过 IP 层路由，因此可以被送进虚拟网卡。系统代理接管不了“不认这项设置的程序”自行发出的 DNS 包；但对遵守 HTTP 或 SOCKS 代理设置的应用，域名本来就可以交给代理解析，本机未必会发出对应查询。这两种情况不能混为一谈。</p><h2 id="自查-换个场景推一遍" tabindex="-1">自查：换个场景推一遍 <a class="header-anchor" href="#自查-换个场景推一遍" aria-label="Permalink to &quot;自查：换个场景推一遍&quot;">​</a></h2><details><summary>题目 1：容器里的两种写法</summary><p>一个 Docker 容器里跑着两个程序。程序 A 用某个 HTTP 库发请求，这个库会自动读取容器里设置的 <code>HTTP_PROXY</code> 环境变量；程序 B 直接用 <code>socket.create_connection</code> 连接目标 IP，不读任何环境变量。容器网络本身没有开 TUN，也没有配置透明重定向。哪个程序的流量会进入代理入口，哪个不会？</p><details><summary>参考答案</summary><p>程序 A 会进入代理入口，因为它主动读取了系统代理设置这张&quot;便签&quot;，把请求改发给了代理地址。程序 B 不会，因为它既不读环境变量，容器也没有 TUN 或路由层面的强制转发。它发出的连接会直接尝试到达目标地址，不经过代理。如果目标不可达，程序 B 会像本章开头的脚本一样卡住直到超时。</p></details></details><details><summary>题目 2：路由器上的透明代理</summary><p>一台路由器对所有经过它的连接做透明代理。客户端不需要做任何配置，路由器会在网络层直接拦截并转发这条连接。这属于&quot;系统代理&quot;那种&quot;应用自愿遵守&quot;的模型吗？如果不是，它更接近本章的哪个机制？</p><details><summary>参考答案</summary><p>不属于。系统代理依赖应用主动读取设置、主动把请求发给代理，客户端完全知情且配合。路由器上的透明代理不需要客户端做任何事，是网络路径上的设备直接拦截数据包再转发。这一点上更接近 TUN 模式&quot;不管应用是否配合，靠路由或转发层面接管&quot;的思路，只是实现的位置在路由器，不是本机虚拟网卡。</p></details></details><h2 id="边界声明" tabindex="-1">边界声明 <a class="header-anchor" href="#边界声明" aria-label="Permalink to &quot;边界声明&quot;">​</a></h2><p>从这一章开始，本课程会带你逐步实现一个教学用的最小代理（mini-proxy）。这里先明确一条贯穿全书的边界：这套实现以及后续所有验证，只应该运行在你自己拥有或已经明确获得授权的环境里，全部自动化测试也只连接本机地址 <code>127.0.0.1</code>。本课程不会讲解如何伪装流量特征、劫持证书或者绕过他人的访问控制，这些是另一类问题，超出&quot;理解代理数据路径原理&quot;这一目标。</p><h2 id="回到开头的问题" tabindex="-1">回到开头的问题 <a class="header-anchor" href="#回到开头的问题" aria-label="Permalink to &quot;回到开头的问题&quot;">​</a></h2><p>现在可以完整回答开头的现象了。浏览器能打开网站，是因为它主动读取了系统代理设置，请求进入了代理的入口。终端里的裸 socket 脚本超时，是因为它不认这项设置，连接根本没有机会进入入口，直接对着一个在你的网络环境里不可达的目标发起 TCP 连接。开启 TUN 之后脚本突然连通，是因为 TUN 在网络层修改了路由表，不再需要应用配合，只要 IP 包经过这张虚拟网卡，代理程序就能接住它。</p><p>三段模型里的&quot;入口&quot;到此讲清楚了。&quot;路由&quot;这一段目前只停留在&quot;由规则引擎判断&quot;这句话上，还没有变成可以运行的代码。接下来几章会先把两种真实的入口协议实现出来，也就是 HTTP 正向代理与 SOCKS5，再回头把路由阶段落实成一个可以用测试验证的函数。</p>',34)])])}const q=a(d,[["render",u]]);export{c as __pageData,q as default};
